import {AUTO_MODEL_ID, getAutoModel} from '@github-ui/copilot-chat/utils/auto-model'
import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import {generateDefaultModel} from '@github-ui/copilot-chat/utils/models'
import {sendEvent} from '@github-ui/hydro-analytics'
import {useSearchParams} from '@github-ui/use-navigate'
import {useEffect, useRef} from 'react'

import LoggedOutView from '../components/LoggedOutView/LoggedOutView'
import {CopilotContext} from './../contexts/CopilotContext'
import {useInitialCopilotContext} from './../hooks/useInitialCopilotContext'

// eslint-disable-next-line @typescript-eslint/no-empty-object-type
export interface CopilotImmersiveLoggedOutProps {}

export const defaultProps: Partial<CopilotImmersiveLoggedOutProps> = {}

const CopilotImmersiveLoggedOut = (props: CopilotImmersiveLoggedOutProps) => {
  const initializedProps: CopilotImmersiveLoggedOutProps = {...defaultProps, ...props}
  // eslint-disable-next-line no-empty-pattern
  const {} = initializedProps

  const [searchParams, setSearchParams] = useSearchParams()
  // Gate the Auto-mode lock so "Auto" doesn't leak on this public surface before launch.
  const isAutoModeLocked = copilotFeatureFlags.autoModePickerFreeEdu
  const defaultModel = isAutoModeLocked ? getAutoModel() : generateDefaultModel()
  const initialModelId = isAutoModeLocked ? AUTO_MODEL_ID : defaultModel.id
  const autoPopulated = useRef(false)

  const {copilotContextValue} = useInitialCopilotContext({defaultModel})

  useEffect(() => {
    if (autoPopulated.current) return
    autoPopulated.current = true

    const queryPrompt = searchParams.get('prompt')
    if (queryPrompt) copilotContextValue.setPrompt(queryPrompt)

    // Picker is non-selectable for logged-out users; drop legacy deep-link params.
    const newSearchParams = new URLSearchParams(searchParams)
    newSearchParams.delete('prompt')
    newSearchParams.delete('model')
    setSearchParams(newSearchParams, {replace: true})
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [searchParams, setSearchParams])

  return (
    <CopilotContext value={copilotContextValue}>
      <LoggedOutView
        initialModelId={initialModelId}
        onIdeListItemClick={(_, ideName) => {
          sendEvent('click', {
            category: 'copilot_loggedOut',
            action: 'ide_option_click',
            label: 'copilot_loggedOut',
            ideName,
          })
        }}
        onProductAnnouncementBannerEvent={event => {
          switch (event) {
            case 'displayed':
              sendEvent('view', {
                category: 'universe_banner',
                action: 'banner_view',
                label: 'banner_universe_loggedOut',
              })
              break
            case 'clicked':
              sendEvent('click', {
                category: 'universe_banner',
                action: 'banner_click_openModal',
                label: 'banner_universe_loggedOut',
              })
              break
            case 'dismissed':
              sendEvent('click', {
                category: 'universe_banner',
                action: 'banner_dismiss',
                label: 'banner_universe_loggedOut',
              })
              break
          }
        }}
        onProductAnnouncementModalEvent={(event, data) => {
          switch (event) {
            case 'opened':
              sendEvent('view', {
                category: 'universe_modal',
                action: 'modal_view',
                label: 'modal_universe_loggedOut',
              })
              break
            case 'closed':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_close',
                label: 'modal_universe_loggedOut',
              })
              break
            case 'tab_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_nav_click',
                label: 'modal_universe_loggedOut',
                navItem: data?.tabName as string,
              })
              break
            case 'main_cta1_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_primary_cta_left_click',
                label: 'modal_universe_loggedOut',
              })
              break
            case 'see_all_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_seeAllAnnouncements_left_click',
                label: 'modal_universe_loggedOut',
              })
              break
            case 'tab_cta1_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_primary_cta_right_click',
                label: 'modal_universe_loggedOut',
                navItem: data?.tabName as string,
                ctaType: 'primary_right',
                ctaUrl: data?.url as string,
                userStatus: 'logged_out',
                positionIndex: data?.tabIndex as number,
              })
              break
            case 'tab_cta2_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_secondary_cta_right_click',
                label: 'modal_universe_loggedOut',
                navItem: data?.tabName as string,
                ctaType: 'secondary_right',
                ctaUrl: data?.url as string,
                userStatus: 'logged_out',
                positionIndex: data?.tabIndex as number,
              })
              break
            case 'tab_link_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_link_right_click',
                label: 'modal_universe_loggedOut',
                navItem: data?.tabName as string,
                ctaType: 'learn_more_right',
                ctaUrl: data?.url as string,
                userStatus: 'logged_out',
                positionIndex: data?.tabIndex as number,
              })
              break
            case 'tab_description_link_clicked':
              sendEvent('click', {
                category: 'universe_modal',
                action: 'modal_description_link_right_click',
                label: 'modal_universe_loggedOut',
                navItem: data?.tabName as string,
                ctaType: 'link',
                ctaUrl: data?.url as string,
                userStatus: 'logged_out',
                positionIndex: data?.tabIndex as number,
              })
              break
          }
        }}
      />
    </CopilotContext>
  )
}

export default CopilotImmersiveLoggedOut
